import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor({ name: uniqueName("Expired COI") });
  // Yesterday's date, in the YYYY-MM-DD form the extraction reads as "Expiry Date".
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const certificate = `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${yesterday}\n`;

  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");
  const insurance = await expectStatus<{ id: string }>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: { name: "expired-coi.txt", mimeType: "text/plain", buffer: Buffer.from(certificate) },
      },
    }),
    201,
  );
  await expect
    .poll(
      async () => {
        const docs = await expectStatus<{ status: string }[]>(
          await member.get(`/api/vendors/${vendor.id}/documents`),
          200,
        );
        return docs.map((d) => d.status);
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const before = await factory.extraction(insurance.id, "reviewer");
  expect(before.status, "insurance extraction awaits review").toBe("pending_review");

  // Act
  const response = await reviewer.post(`/api/extractions/${before.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expired");
  // Re-read it: a refused approval must leave the stored extraction untouched.
  expect((await factory.extraction(insurance.id, "reviewer")).status).toBe("pending_review");
});
